// Bundled frontend files (so no public/ folder is needed)
module.exports={"index.html": "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>RE.UNIQLO Smart Repair Assistant (demo)</title><link rel=\"stylesheet\" href=\"style.css\">\n<header><div><b>RE.UNIQLO</b> Smart Repair</div><nav><a href=\"staff.html\">Staff</a></nav></header><div id=\"mode\" class=\"banner\"></div>\n<main id=\"app\"></main>\n<script>\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));\nconst vnd=n=>new Intl.NumberFormat('en-US').format(n)+' VND';\nlet S={step:0,cat:'',q:'',prod:null,imgs:[],loc:'Front',note:'',scenario:'hole',name:'',email:'',city:'District 1',res:null,opt:null,store:null,consent:false,idem:crypto.randomUUID(),busy:false,err:'',cfg:{},products:[],stores:[]};\nconst api=async(u,o)=>{const r=await fetch(u,o),j=await r.json();if(!r.ok)throw new Error(j.error||'Request failed');return j};\nasync function init(){S.cfg=await api('/api/config');S.products=await api('/api/products');\n $('#mode').className='banner'+(S.cfg.aiMode==='demo'||S.cfg.emailMode==='demo'?' demo':'');\n $('#mode').textContent=`Independent demo prototype, not an official UNIQLO service. AI: ${S.cfg.aiMode.toUpperCase()} \u00b7 Email: ${S.cfg.emailMode.toUpperCase()}`+(S.cfg.missing.length?` \u00b7 Not configured: ${S.cfg.missing.join(', ')}`:'');render()}\nconst steps=()=>`<div class=\"steps\">${[1,2,3,4,5,6].map(i=>`<i class=\"${i<=S.step?'on':''}\"></i>`).join('')}</div>`;\nconst go=n=>{S.step=n;S.err='';render()};\nconst err=()=>S.err?`<p class=\"err\" role=\"alert\">${esc(S.err)}</p>`:'';\nfunction render(){const a=$('#app');\n if(S.step===0)a.innerHTML=`<section class=\"hero\"><h1>Give Your Clothes a Longer Life.</h1><p>Discover the right repair option before visiting a RE.UNIQLO STUDIO.</p><button class=\"btn\" id=\"go\">Start a Repair Assessment</button> <button class=\"btn sec\" id=\"svc\">Explore Repair Services</button></section>\n <div class=\"grid\"><div class=\"card\"><b>Know Before You Go.</b><br>Get an AI-assisted first look at the damage.</div><div class=\"card\"><b>Find the Right Repair.</b><br>See methods and indicative prices.</div><div class=\"card\"><b>Keep Clothes in Use Longer.</b><br>Staff confirm the plan before you travel.</div></div>\n <p class=\"note\">Process: identify garment, upload photos, review AI options, staff confirm by email, visit the store. AI recommends; staff confirm.</p><div id=\"svcl\"></div>`,$('#go').onclick=()=>go(1),$('#svc').onclick=async()=>{S.stores=await api('/api/stores');$('#svcl').innerHTML=S.stores.map(s=>`<div class=\"card\"><b>${esc(s.name)}</b> (demo)<br>${esc(s.address)}<br>${s.sup.map(x=>`<span class=\"pill\">${esc(x)}</span>`).join('')}</div>`).join('')};\n if(S.step===1){const cats=['',...new Set(S.products.map(p=>p.category))],list=S.products.filter(p=>(!S.cat||p.category===S.cat)&&(p.name+p.id).toLowerCase().includes(S.q.toLowerCase()));\n  a.innerHTML=steps()+`<h2>First, Let's Identify Your Garment.</h2><div class=\"row\"><div><label for=\"q\">Product ID or name</label><input id=\"q\" value=\"${esc(S.q)}\" placeholder=\"DEMO-004 or jacket\"></div><div><label for=\"cat\">Category</label><select id=\"cat\">${cats.map(c=>`<option value=\"${c}\" ${c===S.cat?'selected':''}>${c||'All'}</option>`).join('')}</select></div></div><div class=\"grid\" style=\"margin-top:16px\">${list.map(p=>`<div class=\"card ${S.prod?.id===p.id?'sel':''}\" data-id=\"${p.id}\" tabindex=\"0\" role=\"button\"><img src=\"${p.image}\" alt=\"\"><b>${esc(p.name)}</b><br><small>${p.id} \u00b7 ${esc(p.material)}</small></div>`).join('')||'<p>No match. Try another ID or category.</p>'}</div>\n  ${S.prod?`<div class=\"note\"><b>${esc(S.prod.name)}</b> (${S.prod.id}) \u00b7 ${esc(S.prod.category)} \u00b7 ${esc(S.prod.material)}<br>${esc(S.prod.description)}</div>`:''}<button class=\"btn\" id=\"n\" ${S.prod?'':'disabled'}>Confirm garment</button>`;\n  $('#q').oninput=e=>{S.q=e.target.value;const p=e.target.selectionStart;render();$('#q').focus();$('#q').setSelectionRange(p,p)};$('#cat').onchange=e=>{S.cat=e.target.value;render()};\n  document.querySelectorAll('.card[data-id]').forEach(c=>{const f=()=>{S.prod=S.products.find(p=>p.id===c.dataset.id);render()};c.onclick=f;c.onkeydown=e=>e.key==='Enter'&&f()});$('#n').onclick=()=>go(2)}\n if(S.step===2){const dm=S.cfg.aiMode==='demo';\n  a.innerHTML=steps()+`<h2>Show Us What Needs Repair.</h2><p>Add 1) a full garment photo, 2) a close-up of the damage, 3) optionally the care label. JPG, PNG or WEBP, up to 5 MB each. Use daylight and keep the damage in focus.</p><div class=\"drop\" id=\"drop\" tabindex=\"0\">Drag photos here or click to browse<input id=\"f\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\" multiple hidden></div><div class=\"grid\" style=\"margin-top:12px\">${S.imgs.map((d,i)=>`<div class=\"thumb\"><img src=\"${d}\" alt=\"Upload ${i+1}\"><small>${['Full garment','Close-up','Care label'][i]}</small> <button class=\"btn sec\" data-d=\"${i}\">Remove</button></div>`).join('')}</div>\n  <div class=\"row\"><div><label for=\"loc\">Damage location</label><select id=\"loc\">${['Front','Back','Sleeve','Collar','Hem','Pocket','Other'].map(x=>`<option ${x===S.loc?'selected':''}>${x}</option>`).join('')}</select></div><div><label for=\"city\">Preferred area</label><input id=\"city\" value=\"${esc(S.city)}\"></div></div>\n  <label for=\"note\">Tell us more about the damage</label><textarea id=\"note\" rows=\"2\">${esc(S.note)}</textarea>\n  ${dm?`<div class=\"note\"><b>Demo mode:</b> AI Vision is not connected, so photos are NOT analysed. Pick a demo scenario:<select id=\"sc\">${[['hole','Small hole'],['seam','Loose seam'],['button','Missing button'],['zipper','Broken zipper'],['pilling','Pilling'],['unclear','Unclear photo']].map(([v,l])=>`<option value=\"${v}\" ${v===S.scenario?'selected':''}>${l}</option>`).join('')}</select></div>`:''}\n  <div class=\"row\"><div><label for=\"nm\">Full name</label><input id=\"nm\" value=\"${esc(S.name)}\"></div><div><label for=\"em\">Email</label><input id=\"em\" type=\"email\" value=\"${esc(S.email)}\"></div></div>\n  <label><input type=\"checkbox\" id=\"cs\" style=\"width:auto\" ${S.consent?'checked':''}> I consent to sharing my photos and contact details with the selected repair store.</label>${err()}<p><button class=\"btn sec\" id=\"b\">Back</button> <button class=\"btn\" id=\"n\" ${S.busy?'disabled':''}>${S.busy?'Assessing\u2026':'Run assessment'}</button></p>`;\n  const add=async fs=>{for(const f of fs){if(S.imgs.length>=3)break;if(!['image/jpeg','image/png','image/webp'].includes(f.type)){S.err='Only JPG, PNG or WEBP';continue}if(f.size>5e6){S.err='Each image must be under 5 MB';continue}S.imgs.push(await new Promise(r=>{const x=new FileReader();x.onload=()=>r(x.result);x.readAsDataURL(f)}))}keep();render()};\n  const keep=()=>{['loc','note','city','nm','em'].forEach(k=>{const e=$('#'+k);if(e)S[{nm:'name',em:'email'}[k]||k]=e.value});S.consent=$('#cs').checked;if($('#sc'))S.scenario=$('#sc').value};\n  $('#drop').onclick=()=>$('#f').click();$('#f').onchange=e=>add([...e.target.files]);$('#drop').ondragover=e=>{e.preventDefault();$('#drop').classList.add('over')};$('#drop').ondrop=e=>{e.preventDefault();add([...e.dataTransfer.files])};\n  document.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{keep();S.imgs.splice(+b.dataset.d,1);render()});$('#b').onclick=()=>{keep();go(1)};\n  $('#n').onclick=async()=>{keep();if(S.imgs.length<2)return S.err='Add the full garment and a close-up photo.',render();if(!S.name||!/^\\S+@\\S+\\.\\S+$/.test(S.email))return S.err='Enter your name and a valid email.',render();if(!S.consent)return S.err='Consent is required to continue.',render();\n   S.busy=true;S.err='';render();try{S.res=await api('/api/assess',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productId:S.prod.id,images:S.imgs,location:S.loc,note:S.note,scenario:S.scenario})});S.opt=S.res.options[0];S.busy=false;go(3)}catch(e){S.busy=false;S.err=e.message;render()}}}\n if(S.step===3){const r=S.res,x=r.a;\n  a.innerHTML=steps()+`<h2>Here Are Your Repair Options.</h2><div class=\"note\"><b>${esc(r.source)}</b></div><p><span class=\"pill\">${esc(x.damageType)}</span><span class=\"pill\">Severity: ${esc(x.severity)}</span><span class=\"pill\">Confidence: ${esc(x.confidence)}</span><span class=\"pill\">${esc(x.repairability)}</span></p><p>${esc(x.evidence)}<br><small>${esc(x.uncertainty)}</small></p>${x.confidence==='Low'?'<p class=\"err\">Low confidence: please retake clearer photos or visit a store for inspection.</p>':''}\n  <div class=\"grid\">${r.options.map((o,i)=>`<div class=\"card ${S.opt.method===o.method?'sel':''}\" data-o=\"${i}\" tabindex=\"0\" role=\"button\"><b>${esc(o.method)}</b><br>${o.max?vnd(o.min)+' \u2013 '+vnd(o.max):'No charge estimate'}<br><small>${esc(o.turnaround)}</small></div>`).join('')}</div>\n  <p class=\"note\">This is a preliminary AI-assisted assessment based on the information provided. Actual repairability, final repair methods, pricing, and turnaround time must be confirmed by RE.UNIQLO STUDIO staff. Indicative price only. Final pricing is subject to staff confirmation.</p><button class=\"btn sec\" id=\"b\">Back</button> <button class=\"btn\" id=\"n\">Choose a store</button>`;\n  document.querySelectorAll('[data-o]').forEach(c=>{const f=()=>{S.opt=r.options[+c.dataset.o];S.store=null;render()};c.onclick=f;c.onkeydown=e=>e.key==='Enter'&&f()});$('#b').onclick=()=>go(2);$('#n').onclick=()=>go(4)}\n if(S.step===4){api(`/api/stores?method=${encodeURIComponent(S.opt.method)}&city=${encodeURIComponent(S.city)}`).then(l=>{S.stores=l;$('#sl').innerHTML=l.map(s=>`<div class=\"card ${S.store===s.id?'sel':''}\" data-s=\"${s.id}\" tabindex=\"0\" role=\"button\" ${s.compatible?'':'style=\"opacity:.55\"'}><b>${esc(s.name)}</b> ${s.compatible?'<span class=\"ok\">Compatible</span>':'<span class=\"err\">Not listed for this repair</span>'}<br>${esc(s.address)}<br>${esc(s.contact)} \u00b7 ${esc(s.hours)}<br>${s.sup.map(x=>`<span class=\"pill\">${esc(x)}</span>`).join('')}<br><small>${esc(s.limits)}</small> <a href=\"https://www.google.com/maps/search/${encodeURIComponent(s.address)}\" target=\"_blank\" rel=\"noopener\">Directions</a></div>`).join('');document.querySelectorAll('[data-s]').forEach(c=>c.onclick=()=>{const s=S.stores.find(z=>z.id===c.dataset.s);if(!s.compatible)return;S.store=s.id;render()})});\n  a.innerHTML=steps()+`<h2>Find the Right Place for Your Repair.</h2><p class=\"note\">Demo stores only. Not verified real UNIQLO services; no live booking.</p><div class=\"row\"><input id=\"city\" value=\"${esc(S.city)}\" aria-label=\"Area\"><button class=\"btn sec\" id=\"s\">Search</button></div><div id=\"sl\" class=\"grid\" style=\"margin-top:12px\"></div><p><button class=\"btn sec\" id=\"b\">Back</button> <button class=\"btn\" id=\"n\" ${S.store?'':'disabled'}>Review request</button></p>`;\n  $('#s').onclick=()=>{S.city=$('#city').value;render()};$('#b').onclick=()=>go(3);$('#n').onclick=()=>go(5)}\n if(S.step===5){const st=S.stores.find(s=>s.id===S.store),x=S.res.a;\n  a.innerHTML=steps()+`<h2>Review Your Repair Request.</h2><div class=\"note\"><b>${esc(S.name)}</b> \u00b7 ${esc(S.email)}<br>${esc(S.prod.name)} (${S.prod.id}) \u00b7 ${esc(S.prod.material)}<br>AI: ${esc(x.damageType)} \u00b7 ${esc(x.repairability)} \u00b7 confidence ${esc(x.confidence)}<br>Selected: <b>${esc(S.opt.method)}</b> \u00b7 ${S.opt.max?vnd(S.opt.min)+' \u2013 '+vnd(S.opt.max):'n/a'} (indicative)<br>Store: ${esc(st.name)}<br><small>${esc(S.res.source)}</small></div><div class=\"grid\">${S.imgs.map(d=>`<img src=\"${d}\" alt=\"Uploaded photo\" style=\"width:100%\">`).join('')}</div>${err()}<p><button class=\"btn sec\" id=\"b\">Back</button> <button class=\"btn\" id=\"n\" ${S.busy?'disabled':''}>${S.busy?'Submitting\u2026':'Submit for Staff Confirmation'}</button></p>`;\n  $('#b').onclick=()=>go(4);$('#n').onclick=async()=>{S.busy=true;render();try{S.done=await api('/api/cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idem:S.idem,name:S.name,email:S.email,productId:S.prod.id,images:S.imgs,ai:S.res.a,aiSource:S.res.source,method:S.opt.method,storeId:S.store,consent:true})});S.busy=false;go(6)}catch(e){S.busy=false;S.err=e.message;render()}}}\n if(S.step===6){const d=S.done,ok=d.emailStatus==='SENT';a.innerHTML=`<h2>Request ${esc(d.ref)} submitted.</h2><p>Staff will confirm repairability, price, and timing by email to ${esc(S.email)}. Bring the garment and your Reference ID to the store once confirmed.</p><p class=\"${ok?'ok':'note'}\">Staff notification: ${esc(d.emailStatus)}${d.emailError?' \u2014 '+esc(d.emailError):''}</p><a class=\"btn\" href=\"track.html?t=${d.token}\">Track this request</a>`}}\ninit();\n</script>\n", "staff.html": "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Staff review</title><link rel=\"stylesheet\" href=\"style.css\"><header><div><b>RE.UNIQLO</b> Staff Review</div><a href=\"index.html\">Customer site</a></header><div class=\"banner demo\">Local demo auth. Production: Supabase magic link, allowlisted to STAFF_EMAIL.</div><main id=\"a\"></main>\n<script>const esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));const vnd=n=>new Intl.NumberFormat('en-US').format(n)+' VND';\nlet T=sessionStorage.getItem('st'),q='',fs='';const api=async(u,o={})=>{o.headers={...(o.headers||{}),Authorization:'Bearer '+T,'Content-Type':'application/json'};const r=await fetch(u,o),j=await r.json();if(r.status===401&&T){T=null;sessionStorage.removeItem('st');login();throw new Error('Session expired')}if(!r.ok)throw new Error(j.error||'Request failed');return j};\nfunction login(m=''){a.innerHTML=`<h2>Staff login</h2><label for=\"e\">Staff email</label><input id=\"e\"><label for=\"p\">Passcode</label><input id=\"p\" type=\"password\"><p class=\"err\">${esc(m)}</p><button class=\"btn\" id=\"l\">Sign in</button>`;l.onclick=async()=>{try{const r=await fetch('/api/staff/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e.value,passcode:p.value})}),j=await r.json();if(!r.ok)return login(j.error);T=j.token;sessionStorage.setItem('st',T);boot()}catch(x){login(x.message)}}}\nasync function list(){const cs=await api('/api/staff/cases'),n=k=>cs.filter(c=>c.status===k).length,v=cs.filter(c=>(c.ref+c.name+c.product).toLowerCase().includes(q.toLowerCase())&&(!fs||c.status===fs));\na.innerHTML=`<h2>Repair requests</h2><p><span class=\"pill\">Total ${cs.length}</span><span class=\"pill\">New ${n('SUBMITTED_TO_STAFF')}</span><span class=\"pill\">In review ${n('UNDER_STAFF_REVIEW')}</span><span class=\"pill\">Approved/notified ${cs.filter(c=>c.decision==='APPROVED').length}</span><span class=\"pill\">Inspection ${cs.filter(c=>c.decision==='INSPECTION').length}</span><span class=\"pill\">Rejected ${cs.filter(c=>c.decision==='REJECTED').length}</span></p><div class=\"row\"><input id=\"q\" placeholder=\"Search\" value=\"${esc(q)}\"><select id=\"fs\"><option value=\"\">All statuses</option>${['SUBMITTED_TO_STAFF','UNDER_STAFF_REVIEW','APPROVED','INSPECTION_REQUIRED','REJECTED','CUSTOMER_NOTIFIED'].map(s=>`<option ${s===fs?'selected':''}>${s}</option>`).join('')}</select></div><table><tr><th>Ref<th>Customer<th>Product<th>Damage<th>AI<th>Date<th>Status</tr>${v.map(c=>`<tr class=\"link\" data-id=\"${c.id}\"><td>${c.ref}<td>${esc(c.name)}<td>${esc(c.product)}<td>${esc(c.damage)}<td>${esc(c.repairability)}<td>${c.createdAt.slice(0,10)}<td>${c.status}</tr>`).join('')||'<tr><td colspan=7>No requests yet. Submit one from the customer site.</tr>'}</table><p><a href=\"#\" id=\"ob\">View email outbox</a></p>`;\nq_=document.getElementById('q');q_.oninput=ev=>{q=ev.target.value;list().then(()=>{const i=document.getElementById('q');i.focus();i.setSelectionRange(q.length,q.length)})};document.getElementById('fs').onchange=ev=>{fs=ev.target.value;list()};document.querySelectorAll('tr.link').forEach(r=>r.onclick=()=>open_(r.dataset.id));document.getElementById('ob').onclick=async ev=>{ev.preventDefault();const o=await api('/api/staff/outbox');a.innerHTML=`<h2>Email log</h2><p><a href=\"#\" id=\"bk\">Back</a></p><table><tr><th>Time<th>Type<th>To<th>Status</tr>${o.map(x=>`<tr><td>${x.at.slice(0,19)}<td>${x.type}<td>${esc(x.to)}<td>${esc(x.status)}${x.error?' \u2014 '+esc(x.error):''}</tr>`).join('')}</table>`;document.getElementById('bk').onclick=ev2=>{ev2.preventDefault();list()}}}\nasync function open_(id,msg=''){const c=await api('/api/staff/cases/'+id),x=c.ai,st=await fetch('/api/stores').then(r=>r.json()),d=c.decision||{};\na.innerHTML=`<p><a href=\"#\" id=\"bk\">Back</a></p><h2>${c.ref} <span class=\"pill\">${c.status}</span></h2><p class=\"${msg.startsWith('Error')?'err':'ok'}\">${esc(msg)}</p><div class=\"row\"><div class=\"note\"><b>Customer</b><br>${esc(c.name)}<br>${esc(c.email)}<br>Selected store: ${esc(c.storeName)}</div><div class=\"note\"><b>Garment</b><br>${esc(c.product.name)} (${c.product.id})<br>${esc(c.product.material)}</div></div><h3>Photos</h3><div class=\"grid\">${c.photoLinks.map(p=>`<div><img src=\"${p.url}\" style=\"width:100%\" alt=\"${esc(p.type)}\"><small>${esc(p.type)}</small></div>`).join('')}</div>\n<h3>AI report <small>(${esc(c.aiSource)})</small></h3><div class=\"note\">${esc(x.damageType)} \u00b7 severity ${esc(x.severity)} \u00b7 confidence ${esc(x.confidence)} \u00b7 ${esc(x.repairability)}<br>Suggested: ${esc(x.method)}${x.alt?' / '+esc(x.alt):''} \u00b7 Customer chose: ${esc(c.method)}<br>Indicative: ${vnd(c.min)} \u2013 ${vnd(c.max)}<br>Evidence: ${esc(x.evidence)}<br>Uncertainty: ${esc(x.uncertainty)}</div>\n<h3>Staff confirmation</h3><div class=\"row\"><div><label for=\"dc\">Decision</label><select id=\"dc\"><option value=\"APPROVED\">Approved</option><option value=\"INSPECTION\">Requires Physical Inspection</option><option value=\"REJECTED\">Rejected</option></select></div><div><label for=\"mt\">Final repair method</label><input id=\"mt\" list=\"ml\" value=\"${esc(d.method||c.method)}\"><datalist id=\"ml\">${[...new Set(st.flatMap(s=>s.sup))].map(m=>`<option>${esc(m)}`).join('')}</datalist></div></div><div class=\"row\"><div><label for=\"pr\">Final price (VND)</label><input id=\"pr\" type=\"number\" min=\"0\" value=\"${d.price||''}\"></div><div><label for=\"eta\">Estimated completion</label><input id=\"eta\" placeholder=\"e.g. 3 working days\" value=\"${esc(d.eta||'')}\"></div><div><label for=\"sid\">Confirmed store</label><select id=\"sid\">${st.map(s=>`<option value=\"${s.id}\" ${s.id===(d.storeId||c.storeId)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div></div><label for=\"nt\">Notes / rejection reason / inspection instructions</label><textarea id=\"nt\" rows=\"3\">${esc(d.notes||'')}</textarea>\n<p><button class=\"btn\" id=\"go\" ${c.status==='CUSTOMER_NOTIFIED'?'disabled':''}>Confirm &amp; Notify Customer</button> ${c.decision?'<button class=\"btn sec\" id=\"rs\">Resend customer email</button>':''}</p><h3>History</h3><table>${c.events.map(e=>`<tr><td>${e.at.slice(0,19)}<td>${esc(e.d)}</tr>`).join('')}</table>`;\ndocument.getElementById('bk').onclick=ev=>{ev.preventDefault();list()};document.getElementById('go').onclick=async()=>{try{const r=await api(`/api/staff/cases/${id}/decide`,{method:'POST',body:JSON.stringify({decision:dc.value,method:mt.value,price:pr.value,eta:eta.value,storeId:sid.value,notes:nt.value})});open_(id,`Saved. Customer email: ${r.emailStatus}${r.emailError?' \u2014 '+r.emailError:''}`)}catch(e){open_(id,'Error: '+e.message)}};\nif(document.getElementById('rs'))document.getElementById('rs').onclick=async()=>{const r=await api(`/api/staff/cases/${id}/resend`,{method:'POST'});open_(id,`Resend: ${r.emailStatus}${r.emailError?' \u2014 '+r.emailError:''}`)}}\nasync function boot(){try{const id=new URLSearchParams(location.search).get('case');id?await open_(id):await list()}catch(e){login()}}\nT?boot():login();</script>\n", "style.css": ":root{--r:#E60012;--g:#F5F5F5;--t:#222;--m:#6b6b6b}*{box-sizing:border-box}body{margin:0;font:16px/1.5 Helvetica,Arial,sans-serif;color:var(--t);background:#fff}\nheader{border-bottom:1px solid #ddd;padding:14px 24px;display:flex;gap:16px;align-items:center;justify-content:space-between}header b{background:var(--r);color:#fff;padding:6px 10px;font-size:18px}\n.banner{background:#222;color:#fff;font-size:13px;padding:6px 24px}.banner.demo{background:#fff3cd;color:#664d03}\nmain{max-width:920px;margin:0 auto;padding:32px 24px 80px}h1{font-size:40px;line-height:1.1;margin:.2em 0}h2{font-size:28px;margin:.2em 0 .6em}\n.btn{background:var(--r);color:#fff;border:0;padding:13px 26px;font:inherit;font-weight:700;cursor:pointer}.btn.sec{background:#fff;color:var(--t);border:1px solid var(--t)}.btn:disabled{opacity:.4;cursor:not-allowed}.btn:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #222;outline-offset:2px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:12px}.card{border:1px solid #ddd;padding:12px;background:#fff}.card.sel{border:2px solid var(--r)}.card img{width:100%}\ninput,select,textarea{font:inherit;padding:10px;border:1px solid #bbb;width:100%;background:#fff}label{display:block;margin:12px 0 4px;font-weight:700}.row{display:flex;gap:12px;flex-wrap:wrap}.row>*{flex:1;min-width:180px}\n.drop{border:2px dashed #aaa;padding:20px;text-align:center;background:var(--g);cursor:pointer}.drop.over{border-color:var(--r)}.thumb{position:relative}.thumb img{width:100%;aspect-ratio:1;object-fit:cover}\n.note{background:var(--g);padding:12px;font-size:14px;margin:12px 0}.pill{display:inline-block;padding:2px 10px;background:var(--g);font-size:13px;margin-right:6px}.err{color:#b00020;font-weight:700}.ok{color:#0a6b2d;font-weight:700}\ntable{width:100%;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left;font-size:14px}tr.link{cursor:pointer}tr.link:hover{background:var(--g)}\n.steps{display:flex;gap:6px;margin-bottom:24px}.steps i{flex:1;height:4px;background:#ddd}.steps i.on{background:var(--r)}.hero{padding:40px 0;border-bottom:1px solid #ddd;margin-bottom:24px}\n@media(prefers-reduced-motion:no-preference){.card{transition:border-color .15s}}\n", "track.html": "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Track repair</title><link rel=\"stylesheet\" href=\"style.css\"><header><div><b>RE.UNIQLO</b> Smart Repair</div></header><main id=\"a\">Loading\u2026</main>\n<script>const esc=s=>String(s??'').replace(/[&<>\"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[m]));const vnd=n=>new Intl.NumberFormat('en-US').format(n)+' VND';\nconst NEXT={SUBMITTED_TO_STAFF:'Waiting for staff to open your request. Nothing to do yet.',UNDER_STAFF_REVIEW:'Staff are reviewing your photos. Nothing to do yet.',APPROVED:'Bring your garment and Reference ID to the confirmed store.',INSPECTION_REQUIRED:'Bring your garment to the store for a physical inspection.',REJECTED:'See the reason below; contact the store for alternatives.',CUSTOMER_NOTIFIED:'Check your email for the staff decision and next steps.'};\nfetch('/api/track?t='+encodeURIComponent(new URLSearchParams(location.search).get('t')||'')).then(r=>r.json()).then(c=>{if(c.error)return a.textContent='Request not found.';const d=c.decision;\na.innerHTML=`<h2>${esc(c.ref)}</h2><p><span class=\"pill\">${esc(c.status)}</span> ${esc(c.product)}</p><p class=\"note\"><b>Next:</b> ${esc(d?{APPROVED:NEXT.APPROVED,INSPECTION:NEXT.INSPECTION_REQUIRED,REJECTED:NEXT.REJECTED}[d.decision]:NEXT[c.status])}</p>${d?`<p><b>Decision:</b> ${esc(d.decision)}<br>${d.method?`Repair: ${esc(d.method)}<br>`:''}${d.price?`Final price: ${vnd(d.price)}<br>`:''}${d.eta?`Estimated completion: ${esc(d.eta)}<br>`:''}Store: ${esc(d.store.name)}, ${esc(d.store.address)}<br>${esc(d.notes)}</p>`:`<p>Your selection: ${esc(c.method)} (indicative ${vnd(c.min)} \u2013 ${vnd(c.max)}, not final).</p>`}`}).catch(()=>a.textContent='Error loading.')</script>\n", "img/bottoms.svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 120' xmlns:c2pa=\"http://c2pa.org/manifest\"><rect width='120' height='120' fill='#F5F5F5'/><path d='M36 18h48l6 90H66L60 52l-6 56H30z' fill='#fff' stroke='#222' stroke-width='2.5' stroke-linejoin='round'/><metadata><c2pa:manifest></c2pa:manifest></metadata></svg>\n", "img/knitwear.svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 120' xmlns:c2pa=\"http://c2pa.org/manifest\"><rect width='120' height='120' fill='#F5F5F5'/><path d='M28 30l22-10q10 12 20 0l22 10 12 26-14 6v38H30V62l-14-6z' fill='#fff' stroke='#222' stroke-width='2.5' stroke-linejoin='round'/><metadata><c2pa:manifest></c2pa:manifest></metadata></svg>\n", "img/outerwear.svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 120' xmlns:c2pa=\"http://c2pa.org/manifest\"><rect width='120' height='120' fill='#F5F5F5'/><path d='M32 26l20-8h16l20 8 14 30-12 6v46H30V62l-12-6zM60 18v90' fill='#fff' stroke='#222' stroke-width='2.5' stroke-linejoin='round'/><metadata><c2pa:manifest></c2pa:manifest></metadata></svg>\n", "img/shirts.svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 120' xmlns:c2pa=\"http://c2pa.org/manifest\"><rect width='120' height='120' fill='#F5F5F5'/><path d='M30 28l20-8 10 12 10-12 20 8 12 24-14 6v44H32V58l-14-6zM60 32v70' fill='#fff' stroke='#222' stroke-width='2.5' stroke-linejoin='round'/><metadata><c2pa:manifest></c2pa:manifest></metadata></svg>\n", "img/tops.svg": "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 120' xmlns:c2pa=\"http://c2pa.org/manifest\"><rect width='120' height='120' fill='#F5F5F5'/><path d='M30 30l20-10q10 10 20 0l20 10 12 22-14 6v42H32V58l-14-6z' fill='#fff' stroke='#222' stroke-width='2.5' stroke-linejoin='round'/><metadata><c2pa:manifest></c2pa:manifest></metadata></svg>\n"};
